from __future__ import annotations

import base64
import json
import os
import re
import sys
from pathlib import Path

import requests

# Caption is deliberately excluded: the trusted caption should come from PDF text,
# not be regenerated by the VLM. Short fields reduce schema-bound truncation.
VISION_SCHEMA = {
    "type": "object",
    "properties": {
        "figure_type": {
            "type": "string",
            "enum": ["architecture diagram", "flowchart", "line chart", "bar chart", "scatter plot", "table", "other", "unclear"],
        },
        "visible_labels": {
            "type": "array", "maxItems": 8,
            "items": {"type": "string", "maxLength": 50},
        },
        "relationships": {
            "type": "array", "maxItems": 4,
            "items": {"type": "string", "maxLength": 100},
        },
        "chart_axes_and_units": {
            "type": "array", "maxItems": 4,
            "items": {"type": "string", "maxLength": 80},
        },
        "main_takeaway": {"type": "string", "maxLength": 140},
        "uncertainties": {
            "type": "array", "maxItems": 2,
            "items": {"type": "string", "maxLength": 90},
        },
    },
    "required": ["figure_type", "visible_labels", "relationships", "chart_axes_and_units", "main_takeaway", "uncertainties"],
    "additionalProperties": False,
}

PROMPT = """Analyze this scientific-paper visual. Return ONLY JSON matching the schema.
- Prioritize the figure's core components and information flow.
- List at most 6 important labels and 3 key relationships; no duplicates.
- For diagrams, use relationships for arrows/flows and leave chart_axes_and_units empty.
- For charts, record only readable axes, units, legends, and trends. Never guess numbers.
- Do not generate or paraphrase a caption; the real caption is extracted separately from the PDF.
- Some diagrams contain example questions or sample data. Do not answer them; mention them only if necessary to explain the figure.
- Keep main_takeaway to one complete sentence of at most 18 words.
- If a label or connection is unclear, state that in uncertainties. Do not infer invisible details.
- Keep every string concise and complete. Do not stop a sentence mid-word."""


def main() -> int:
    if len(sys.argv) not in (2, 3):
        print('Usage: python src\\ingestion\\test_vision.py "path\\to\\image.png" ["caption from PDF"]')
        return 2

    image_path = Path(sys.argv[1]).expanduser().resolve()
    source_caption = sys.argv[2].strip() if len(sys.argv) == 3 else ""
    if not image_path.is_file():
        print(f"ERROR: image file not found: {image_path}")
        return 2

    model = os.getenv("VISION_MODEL", "qwen2.5vl:3b")
    base_url = os.getenv("OLLAMA_BASE_URL", "http://localhost:11434").rstrip("/")
    output_tokens = int(os.getenv("VISION_NUM_PREDICT", "300"))
    payload = {
        "model": model,
        "stream": False,
        "format": VISION_SCHEMA,
        "keep_alive": "10m",
        "messages": [{
            "role": "user",
            "content": PROMPT,
            "images": [base64.b64encode(image_path.read_bytes()).decode("ascii")],
        }],
        "options": {"temperature": 0, "num_predict": output_tokens, "num_ctx": 4096},
    }

    print(f"Model: {model}")
    print(f"Image: {image_path}")
    if source_caption:
        print(f"Caption from PDF: {source_caption}")
    print(f"Output token budget: {output_tokens}")
    print("Running bounded vision extraction; CPU inference may be slow...")

    try:
        response = requests.post(f"{base_url}/api/chat", json=payload, timeout=(15, 360))
        response.raise_for_status()
        result = response.json()
        raw = result.get("message", {}).get("content", "").strip()
        print("Done reason:", result.get("done_reason", "not supplied"))
        if result.get("total_duration") is not None:
            print("Total duration (seconds):", round(result["total_duration"] / 1e9, 2))
        if result.get("prompt_eval_count") is not None:
            print("Prompt tokens:", result["prompt_eval_count"])
        if result.get("eval_count") is not None:
            print("Output tokens:", result["eval_count"])

        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError as exc:
            print("ERROR: invalid JSON:", exc)
            print("RAW RESPONSE (first 4000 chars):\n", raw[:4000])
            return 1

        # Schema-bound strings can still be valid JSON while semantically cut off.
        takeaway = parsed.get("main_takeaway", "").strip()
        if takeaway and not re.search(r"[.!?]$", takeaway):
            print("WARNING: main_takeaway may be truncated; review before indexing.")
        if result.get("done_reason") == "length":
            print("WARNING: model stopped at output token limit.")

        print("\nVISION JSON\n===========")
        print(json.dumps(parsed, ensure_ascii=False, indent=2))
        if source_caption:
            print("\nTRUSTED PDF CAPTION (kept separate from model output)\n====================================================")
            print(source_caption)
        return 0

    except requests.Timeout:
        print("ERROR: request timed out. Try a smaller crop or hosted vision inference.")
        return 1
    except requests.RequestException as exc:
        print(f"ERROR calling Ollama: {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
